using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using MongoDB.Driver; using SmartSolarMicrogrid.Api.Configuration; using SmartSolarMicrogrid.Api.Data; using SmartSolarMicrogrid.Api.DTOs; using SmartSolarMicrogrid.Api.Models; using SmartSolarMicrogrid.Api.Services;
namespace SmartSolarMicrogrid.Api.Controllers;
[ApiController][Route("api/auth")]public sealed class AuthController(IAuthService service):ControllerBase{[AllowAnonymous][HttpPost("login")]public async Task<ActionResult<LoginResponse>>Login(LoginRequest r)=>Ok(await service.LoginAsync(r));}
[ApiController][Authorize(Roles=Roles.Backoffice)][Route("api/users")]public sealed class UsersController(IUserService s):ControllerBase{[HttpGet]public async Task<ActionResult<List<User>>>Get()=>Ok(await s.GetAsync());[HttpPost]public async Task<ActionResult<User>>Create(UserRequest r){var u=await s.CreateAsync(r);return CreatedAtAction(nameof(Get),new{id=u.Id},u);}[HttpPut("{id}")]public async Task<ActionResult<User>>Update(string id,UserUpdateRequest r)=>Ok(await s.UpdateAsync(id,r));}
[ApiController][Route("api/prosumers")]public sealed class ProsumersController(IProsumerService s):ControllerBase{[AllowAnonymous][HttpPost("register")]public async Task<ActionResult<Prosumer>>Register(ProsumerRequest r)=>Ok(await s.RegisterAsync(r));[Authorize][HttpGet("me")]public async Task<ActionResult<Prosumer>>Me()=>Ok(await s.GetAsync(Nic()));[Authorize(Roles=Roles.Prosumer)][HttpPut("me")]public async Task<ActionResult<Prosumer>>Update(ProsumerUpdateRequest r)=>Ok(await s.UpdateAsync(Nic(),r));[Authorize(Roles=Roles.Prosumer)][HttpPost("me/deactivation-request")]public async Task<IActionResult>Deactivate(){await s.RequestDeactivationAsync(Nic());return NoContent();}private string Nic()=>User.FindFirstValue("nic")??throw new InvalidOperationException("Prosumer identity required.");}
[ApiController][Route("api/stations")]public sealed class StationsController(IStationService s):ControllerBase{[AllowAnonymous][HttpGet]public async Task<ActionResult<List<SolarStationInfo>>>Get([FromQuery]bool activeOnly=true)=>Ok(await s.GetAsync(activeOnly));[Authorize(Roles=Roles.Backoffice+","+Roles.GridOperator)][HttpPost]public async Task<ActionResult<SolarStationInfo>>Create(StationRequest r){var x=await s.CreateAsync(r);return CreatedAtAction(nameof(Get),new{id=x.Id},x);}[Authorize(Roles=Roles.Backoffice+","+Roles.GridOperator)][HttpPut("{id}")]public async Task<ActionResult<SolarStationInfo>>Update(string id,StationRequest r)=>Ok(await s.UpdateAsync(id,r));[Authorize(Roles=Roles.Backoffice+","+Roles.GridOperator)][HttpDelete("{id}")]public async Task<IActionResult>Deactivate(string id){await s.DeactivateAsync(id);return NoContent();}}
[ApiController][Route("api/slots")]public sealed class SlotsController(ISlotService s):ControllerBase{[AllowAnonymous][HttpGet]public async Task<ActionResult<List<EnergyBookingSlot>>>Get([FromQuery]string? stationId)=>Ok(await s.GetAsync(stationId));[Authorize(Roles=Roles.Backoffice+","+Roles.GridOperator)][HttpPost]public async Task<ActionResult<EnergyBookingSlot>>Create(SlotRequest r)=>Ok(await s.CreateAsync(r));[Authorize(Roles=Roles.Backoffice+","+Roles.GridOperator)][HttpPut("{id}")]public async Task<ActionResult<EnergyBookingSlot>>Update(string id,SlotRequest r)=>Ok(await s.UpdateAsync(id,r));[Authorize(Roles=Roles.Backoffice+","+Roles.GridOperator)][HttpDelete("{id}")]public async Task<IActionResult>Delete(string id){await s.DeleteAsync(id);return NoContent();}}
[ApiController][Authorize(Roles=Roles.Prosumer)][Route("api/reservations")]public sealed class ReservationsController(IReservationService s):ControllerBase{[HttpGet]public async Task<ActionResult<List<EnergyReservation>>>Get([FromQuery]string? state)=>Ok(await s.QueryAsync(Nic(),state));[HttpPost]public async Task<ActionResult<EnergyReservation>>Create(ReservationRequest r)=>Ok(await s.CreateAsync(Nic(),r));[HttpPut("{id}")]public async Task<ActionResult<EnergyReservation>>Update(string id,ReservationUpdateRequest r)=>Ok(await s.UpdateAsync(id,Nic(),r));[HttpDelete("{id}")]public async Task<IActionResult>Cancel(string id){await s.CancelAsync(id,Nic());return NoContent();}private string Nic()=>User.FindFirstValue("nic")??throw new InvalidOperationException("Prosumer identity required.");}
[ApiController][Authorize(Roles=Roles.GridOperator+","+Roles.Backoffice)][Route("api/operator")]public sealed class OperatorController(IReservationService s):ControllerBase{[HttpPost("verify-qr")]public async Task<ActionResult<EnergyReservation>>Verify(QrVerifyRequest r)=>Ok(await s.VerifyAsync(r.QrToken));[HttpPost("reservations/{id}/finalize")]public async Task<ActionResult<EnergyReservation>>Finalize(string id)=>Ok(await s.FinalizeAsync(id,User.Identity?.Name??"operator"));}
[ApiController][Authorize(Roles=Roles.All)][Route("api/dashboard")]public sealed class DashboardController(MongoContext db):ControllerBase{[HttpGet]public async Task<ActionResult<DashboardResponse>>Get(){var now=DateTime.UtcNow;var stations=await db.Stations.CountDocumentsAsync(x=>x.IsActive);var slots=await db.Slots.Find(x=>x.IsActive&&x.EndTime>now).ToListAsync();var pending=await db.Reservations.CountDocumentsAsync(x=>x.Status==ReservationStatus.Pending||x.Status==ReservationStatus.Confirmed);var completed=await db.Reservations.CountDocumentsAsync(x=>x.Status==ReservationStatus.Completed);return Ok(new DashboardResponse((int)stations,slots.Count,(int)pending,(int)completed,slots.Sum(x=>x.AvailableKwh)));}}
